const localeColumn: Record<AppLocale, number> = {
  en: 1, "zh-Hans": 2, es: 3, ja: 4, de: 5, fr: 6, ko: 7,
  "pt-BR": 8, it: 9, ru: 10, ar: 11, tr: 12,
};

export function hasTranslationFor(english: string): boolean {
  return rows.some((row) => row[1] === english);
}

export function hasMessageKey(key: string): boolean {
  return rows.some((row) => row[0] === key);
}

export function createLocalizer(locale: AppLocale) {
  const byKey = new Map(rows.map((row) => [row[0], row[localeColumn[locale]]!]));
  const englishToKey = new Map(rows.map((row) => [row[1], row[0]]));
  const format = (value: string, params?: Record<string, string | number>): string =>
    params
      ? value.replace(/\{([^}]+)\}/g, (_match, name: string) => String(params[name] ?? `{${name}}`))
      : value;
  const t = (key: string, params?: Record<string, string | number>): string =>
    format(byKey.get(key) ?? rows.find((row) => row[0] === key)?.[1] ?? key, params);
  const text = (english: string): string => {
    const key = englishToKey.get(english);
    return key ? t(key) : english;
  };
  return { locale, t, text };
}

export type Localizer = ReturnType<typeof createLocalizer>;

export function localizeDom(root: ParentNode, i18n: Localizer): void {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node: Node | null;
  while ((node = walker.nextNode())) {
    const value = node.nodeValue ?? "";
    const trimmed = value.trim();
    if (!trimmed) continue;
    const translated = i18n.text(trimmed);
    if (translated === trimmed) continue;
    node.nodeValue = `${value.match(/^\s*/)?.[0] ?? ""}${translated}${value.match(/\s*$/)?.[0] ?? ""}`;
  }
  for (const element of root.querySelectorAll<HTMLElement>("[aria-label], [title]")) {
    for (const attribute of ["aria-label", "title"] as const) {
      const value = element.getAttribute(attribute);
      if (value) element.setAttribute(attribute, i18n.text(value));
    }
  }
}

