export function localizedEmptyStateHtml(locale: AppLocale, t: Localizer["t"]): string | null {
  if (locale === "en") return null;
  const [title, intro, how] = emptyCopy[locale];
  return `<h1>${title}</h1><p>${intro}</p><p><b>.musicxml · .xml · .mxl · .mid · .midi</b></p>
    <div class="empty-actions" aria-label="${t("chooseScore")}">
      <button id="empty-open" class="primary-button large" type="button">${t("openScore")}</button>
      <button id="demo-choir-open" class="secondary-button large" type="button">${t("demoChoir")}</button>
      <button id="demo-piano-open" class="secondary-button large" type="button">${t("demoPiano")}</button>
    </div><p>${how}</p>`;
}
